#include <stdio.h>

int bound(const int values[], int n, int target, int strict) {
    int low = 0, high = n;
    while (low < high) {
        int mid = low + (high - low) / 2;
        if (values[mid] < target || (strict && values[mid] == target)) low = mid + 1;
        else high = mid;
    }
    return low;
}

int main(void) {
    int n, values[100], target;
    if (scanf("%d", &n) != 1) return 1;
    for (int i = 0; i < n; i++) if (scanf("%d", &values[i]) != 1) return 1;
    if (scanf("%d", &target) != 1) return 1;
    int first = bound(values, n, target, 0);
    if (first == n || values[first] != target) puts("-1 -1");
    else printf("%d %d\n", first, bound(values, n, target, 1) - 1);
    return 0;
}

