unlink-matches.main.c:
#include <stdio.h>
#include <stdlib.h>

typedef struct Node { int value; struct Node *next; } Node;
void release(Node *p) {
    while (p) {
        Node *next = p->next;
        free(p);
        p = next;
    }
}

int main(void) {
    int n, target;
    Node *head = NULL;
    if (scanf("%d", &n) != 1) return 1;
    for (int i = 0; i < n; i++) {
        int value;
        if (scanf("%d", &value) != 1) { release(head); return 1; }
        Node *node = malloc(sizeof *node);
        if (!node) { release(head); return 1; }
        *node = (Node){value, head};
        head = node;
    }
    if (scanf("%d", &target) != 1) { release(head); return 1; }
    Node **link = &head;
    while (*link) {
        Node *node = *link;
        if (node->value == target) {
            *link = node->next;
            free(node);
        } else {
            link = &node->next;
        }
    }
    if (!head) puts("EMPTY");
    for (Node *p = head; p; p = p->next) printf("%d\n", p->value);
    release(head);
    return 0;
}
